from itertools import combinations


def _route(minimum, exact):
    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bits.get(source, 0)
        coupons = data["coupons"]
        start = (source, initial_mask, 0)
        best = {start: data["start"]}
        queue = [(data["start"], source, initial_mask, 0)]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full and
                    (used == coupons if exact else used <= coupons)):
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupons:
                    duration = max(minimum, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                next_mask = mask | bits.get(edge["v"], 0)
                for duration, next_used in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_used)
                    if next_time < best.get(next_state, float("inf")):
                        best[next_state] = next_time
                        heapq.heappush(queue, (next_time, edge["v"], next_mask, next_used))
        return {"arrival": None}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator, denominator=10000):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    initial = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
    best_vector = None
    best_assignment = None

    def has_cycle(assignment):
        edges = {name: [] for name in assignment}
        for name, version in assignment.items():
            row = next(row for row in packages[name] if row["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                edges[name].append(dep["name"])
        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        return not all(visit(name) for name in edges)

    def search(assignment, constraints):
        nonlocal best_vector, best_assignment
        pending = [name for name in constraints if name not in assignment]
        if not pending:
            if has_cycle(assignment):
                return
            vector = tuple(assignment.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_assignment = dict(assignment)
            return

        name = pending[0]
        intervals = constraints[name]
        rows = [row for row in packages.get(name, [])
                if all(low <= row["version"] <= high for low, high in intervals)
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            next_assignment = dict(assignment)
            next_assignment[name] = version
            next_constraints = {key: list(value) for key, value in constraints.items()}
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                dep_name = dep["name"]
                interval = (dep["min"], dep["max"])
                next_constraints.setdefault(dep_name, []).append(interval)
                if dep_name in next_assignment and not all(
                        low <= next_assignment[dep_name] <= high
                        for low, high in next_constraints[dep_name]):
                    valid = False
                    break
            if valid:
                search(next_assignment, next_constraints)

    search({}, initial)
    if best_assignment is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_assignment}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for selected in combinations(options, k):
        ids = {job["id"] for job in selected}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active_ends = []
        overlap = False
        for job in sorted(selected, key=lambda row: (row["start"], row["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                overlap = True
                break
        if overlap:
            continue
        chosen_ids = tuple(sorted(ids))
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and chosen_ids < best_ids)):
            best_value = value
            best_ids = chosen_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


